using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using Newtonsoft.Json;
using WF=System.Windows.Forms;

namespace PhotoTutor {
 internal static class AnalysisStabilityChecks {
  static readonly BindingFlags flags=BindingFlags.NonPublic|BindingFlags.Instance;
  static void Pump(Func<bool> done,int ms=12000){var clock=Stopwatch.StartNew();while(!done()){WF.Application.DoEvents();Thread.Sleep(10);if(clock.ElapsedMilliseconds>ms)throw new TimeoutException("test deadline");}WF.Application.DoEvents();}
  static void Wait(Task task){Pump(()=>task.IsCompleted);task.GetAwaiter().GetResult();}
  static WF.Label Status(QuestionBoardDialog board)=>(WF.Label)typeof(QuestionBoardDialog).GetField("status",flags)!.GetValue(board)!;
  internal static int Run(string root){Directory.CreateDirectory(root);Settings.IsolatedTestRoot=Path.Combine(root,"runtime");Settings.IsolatedLegacyPath=Path.Combine(root,"absent");Entry.OfflineUiTesting=true;var checks=new List<object>();int failed=0;
   void Check(string name,Action action){try{AnalysisWorker.FaultForTest=null;AnalysisWorker.TimeoutForTest=0;action();checks.Add(new{name,passed=true});}catch(Exception error){failed++;checks.Add(new{name,passed=false,error=error.ToString()});}finally{AnalysisWorker.FaultForTest=null;AnalysisWorker.TimeoutForTest=0;}}
   using(var workspace=new QuestionWorkspace(Settings.DataRoot)){var page=workspace.Add(MultiRegionChecks.PrintedPage(),"synthetic printed questions");
    Check("actual isolated OCR returns question proposals and preserves original dimensions",()=>{var result=CandidateDetector.Detect(page,CancellationToken.None).GetAwaiter().GetResult();if(!result.Language.StartsWith("PP-OCRv6")||!result.OcrAvailable||result.Regions.Count<2||AnalysisWorker.ActiveWorkers!=0||!File.Exists(page.File))throw new Exception(result.Message);File.WriteAllText(Path.Combine(root,"worker-success.json"),JsonConvert.SerializeObject(new{result.Seconds,result.OcrAvailable,result.Language,result.OcrPasses,count=result.Regions.Count,page.Width,page.Height},Formatting.Indented));});
    Check("clear small text in a native 1200 by 768 frame is not rejected by a blanket pixel-height cutoff",()=>{var scaled=new System.Windows.Media.Imaging.TransformedBitmap(page.Decode(),new System.Windows.Media.ScaleTransform(.48,.48));scaled.Freeze();var visual=new System.Windows.Media.DrawingVisual();using(var drawing=visual.RenderOpen()){drawing.DrawRectangle(System.Windows.Media.Brushes.White,null,new Rect(0,0,1200,768));drawing.DrawImage(scaled,new Rect(312,0,576,768));}var frame=new System.Windows.Media.Imaging.RenderTargetBitmap(1200,768,96,96,System.Windows.Media.PixelFormats.Pbgra32);frame.Render(visual);frame.Freeze();using(var small=new QuestionWorkspace(Settings.DataRoot)){var source=small.Add(frame,"clear software camera frame");var result=CandidateDetector.Detect(source,CancellationToken.None).GetAwaiter().GetResult();File.WriteAllText(Path.Combine(root,"small-clear-frame.json"),JsonConvert.SerializeObject(new{result.Seconds,result.DetailHeight,count=result.Regions.Count,source.Width,source.Height}));if(result.Regions.Count<2||source.Width!=1200||source.Height!=768)throw new Exception(result.Message);}});
    Check("abnormal worker exit does not terminate the board or remove the original page",()=>{AnalysisWorker.FaultForTest="crash";using(var board=new QuestionBoardDialog(workspace,false){AutoAnalyze=false,ShowInTaskbar=false,StartPosition=WF.FormStartPosition.Manual,Location=new System.Drawing.Point(-12000,-12000)}){board.Show();WF.Application.DoEvents();board.AutoAnalyze=true;board.StartAnalysis();Wait(board.AnalysisTask);if(board.IsDisposed||!Status(board).Text.Contains("异常退出")||!File.Exists(page.File)||AnalysisWorker.ActiveWorkers!=0)throw new Exception(Status(board).Text);board.Close();}});
    Check("hung worker is bounded while WinForms timers keep running",()=>{AnalysisWorker.FaultForTest="hang";AnalysisWorker.TimeoutForTest=850;using(var board=new QuestionBoardDialog(workspace,false){AutoAnalyze=false,ShowInTaskbar=false,StartPosition=WF.FormStartPosition.Manual,Location=new System.Drawing.Point(-12000,-12000)})using(var timer=new WF.Timer{Interval=25}){int ticks=0;timer.Tick+=(_,__)=>ticks++;board.Show();WF.Application.DoEvents();timer.Start();board.AutoAnalyze=true;var clock=Stopwatch.StartNew();board.StartAnalysis();Wait(board.AnalysisTask);timer.Stop();if(clock.ElapsedMilliseconds>2500||ticks<8||board.IsDisposed||!Status(board).Text.Contains("等待过久")||AnalysisWorker.ActiveWorkers!=0)throw new Exception("UI ticks="+ticks+" "+Status(board).Text);File.WriteAllText(Path.Combine(root,"timeout-responsive.json"),JsonConvert.SerializeObject(new{ticks,milliseconds=clock.ElapsedMilliseconds,originalExists=File.Exists(page.File),activeWorkers=AnalysisWorker.ActiveWorkers}));board.Close();}});
    Check("manual selection cancels a hung worker and retains all previous IDs and coordinates",()=>{AnalysisWorker.FaultForTest="hang";using(var board=new QuestionBoardDialog(workspace,false){AutoAnalyze=false,ShowInTaskbar=false,StartPosition=WF.FormStartPosition.Manual,Location=new System.Drawing.Point(-12000,-12000)}){board.Show();WF.Application.DoEvents();board.AppendDrawn(new Int32Rect(40,60,300,180));string first=workspace.Active.Regions.Last();var rect=workspace.Regions.Single(r=>r.Id==first).Bounds;board.AutoAnalyze=true;board.StartAnalysis();Pump(()=>AnalysisWorker.ActiveWorkers>0);board.AppendDrawn(new Int32Rect(60,360,300,180));Wait(board.AnalysisTask);if(workspace.Regions.Single(r=>r.Id==first).Bounds!=rect||workspace.Active.Regions.Count!=2||AnalysisWorker.ActiveWorkers!=0||!Status(board).Text.Contains("已保留"))throw new Exception("manual selection was replaced by a cancelled callback");board.Close();}});
    Check("corrupt worker output is rejected without installing candidates",()=>{AnalysisWorker.FaultForTest="invalid";var result=CandidateDetector.Detect(page,CancellationToken.None).GetAwaiter().GetResult();if(result.Regions.Count!=0||!result.Message.Contains("未完成")||!File.Exists(page.File))throw new Exception("bad IPC accepted");});
    Check("three cancel/restart cycles leave no live child processes",()=>{AnalysisWorker.FaultForTest="hang";for(int i=0;i<3;i++){using(var cts=new CancellationTokenSource()){var task=CandidateDetector.Detect(page,cts.Token);Pump(()=>AnalysisWorker.ActiveWorkers>0);cts.Cancel();try{Wait(task);throw new Exception("not cancelled");}catch(OperationCanceledException){}if(AnalysisWorker.ActiveWorkers!=0)throw new Exception("orphan worker");}}});
    Check("returning to an unchanged page uses cached results instead of another worker",()=>{using(var board=new QuestionBoardDialog(workspace,false){ShowInTaskbar=false,StartPosition=WF.FormStartPosition.Manual,Location=new System.Drawing.Point(-12000,-12000)}){board.Show();Pump(()=>typeof(QuestionBoardDialog).GetField("analysis",flags)!.GetValue(board)!=null);Wait(board.AnalysisTask);if(!workspace.Regions.Any(r=>r.Candidate))throw new Exception(Status(board).Text);int pid=AnalysisWorker.LastWorkerPid;board.StartAnalysis();Wait(board.AnalysisTask);if(pid!=AnalysisWorker.LastWorkerPid||!Status(board).Text.Contains("已复用"))throw new Exception("OCR repeated");board.Close();}});
    Check("diagnostics contain metadata and no original path or recognized question text",()=>{var files=Directory.GetFiles(Path.Combine(Settings.DataRoot,"diagnostics"));string value=string.Join("",files.Select(File.ReadAllText));if(value.Contains(page.File)||value.Contains("TEST_API_KEY")||!value.Contains("analysis-worker-exit")||!value.Contains("analysis-complete"))throw new Exception("diagnostics omitted evidence or retained private input");});
   }
   Entry.OfflineUiTesting=false;File.WriteAllText(Path.Combine(root,"识别隔离与交互稳定性.json"),JsonConvert.SerializeObject(new{version="1.6.0",failed,checks,cloudModelCalls=0,localOcr=true,physicalCamera=false,quarantinePreventionClaimed=false},Formatting.Indented));return failed==0?0:1;
  }
 }
}
